  isr_adapter_args = kmm_calloc(1, sizeof(struct intr_adapter_to_nuttx));
  if (isr_adapter_args == NULL)
    {
      irqerr("Failed to kmm_calloc\n");
      return ESP_ERR_NO_MEM;
    }

  isr_adapter_args->handler = handler;
  isr_adapter_args->arg     = arg;

